SELECT

FROM bp_factory_room

    LEFT JOIN bm_resource_permission ON bm_resource_permission.resource_id = bp_factory_room.id



        AND name LIKE CONCAT('%',#{param.name},'%')


        AND module_id = #{param.moduleId}


        AND code LIKE CONCAT('%', #{param.code}, '%')


        AND enable = #{param.enable}


        AND module_id IN

            #{moduleId}



        AND bm_resource_permission.dept_id IN

            #{deptId}



        AND status = #{param.status}

    AND bp_factory_room.is_deleted = 0

group by bp_factory_room.id


        order by bp_factory_room.status desc ,bp_factory_room.`name` DESC


        order by bp_factory_room.code asc

SELECT room.id, room.code, room.name, room.status, room.enable, room.time_limit, room.expire_time, room.description, room.operator, room.operate_time, room.operate_id, room.module_id, room.create_by, room.update_by, room.create_time, room.update_time, room.clean_level, room.three_d_model_id, room.is_deleted,bftf.id floorId, bftf.name floorName, bft.name tenementName, bfl.name moduleName FROM bp_factory_room room LEFT JOIN bp_factory_line_room bflr ON room.id = bflr.room_id and bflr.is_deleted = 0 LEFT JOIN bp_factory_line bfl ON bflr.line_id = bfl.id and bfl.is_deleted = 0 LEFT JOIN bp_factory_tenement_floor bftf ON bftf.id = room.floor_id and bftf.is_deleted = 0 LEFT JOIN bp_factory_tenement bft ON bftf.tenement_id = bft.id and bft.is_deleted = 0
AND bflr.line_id in
#{productLine}
AND room.floor_id in
#{floor}
AND room.id in
#{room}
AND room.clean_level in
#{cleanLevel}
AND bft.id in
#{tenement}
